using UnityEngine;using System.Collections;using System.IO;using System.Collections.Generic;
public class RevisionCapture:MonoBehaviour {
 Camera cam;RenderTexture rt;Texture2D tex;int frame;string folder;List<string> marks=new List<string>();List<string> poses=new List<string>();
 IEnumerator Start(){Application.runInBackground=true;var game=FindAnyObjectByType<DreamscapeCampaign>();var intro=game.GetComponent<ProductionOpening>();intro.Finish();intro.enabled=false;game.GetComponent<ProductionMenu>().enabled=false;game.enabled=false;game.player.GetComponent<Dreamscape.Characters.PlayerInputController>().enabled=false;cam=game.view;cam.GetComponent<Dreamscape.CameraSystem.FirstPersonCamera>().enabled=false;cam.transform.Find("First person sleeves and hands").gameObject.SetActive(false);Time.captureFramerate=24;QualitySettings.vSyncCount=0;folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../../work/trailer-revisao/frames"));Directory.CreateDirectory(folder);rt=new RenderTexture(1280,720,24);tex=new Texture2D(1280,720,TextureFormat.RGB24,false);cam.targetTexture=rt;foreach(var l in FindObjectsByType<Light>())if(l.type!=LightType.Directional)l.enabled=Mathf.Abs(l.transform.position.x+40)<15;marks.Add("opening,"+frame);
var actor=GameObject.Find("Carlinhos opening");var walk=actor.GetComponent<TrailerWalkAnimation>();walk.seated=false;walk.sleep=0;walk.ponder=false;walk.gait=1;
 for(float t=0;t<2.7f;t+=Time.deltaTime){actor.transform.position=new Vector3(-40,0,3+t*1.25f);cam.transform.position=actor.transform.position+new Vector3(-1.3f,1.45f,2.8f);cam.transform.LookAt(actor.transform.position+Vector3.up*1.2f);yield return null;}walk.gait=0;walk.ponder=true;for(float t=0;t<1.3f;t+=Time.deltaTime){cam.transform.position=actor.transform.position+new Vector3(-.7f,1.45f,1.6f-t*.2f);cam.transform.LookAt(actor.transform.position+Vector3.up*1.4f);yield return null;}
 walk.ponder=false;walk.gait=1;for(float t=0;t<1.8f;t+=Time.deltaTime){actor.transform.position=Vector3.Lerp(new Vector3(-40,0,6.375f),new Vector3(-40,0,9.1f),t/1.8f);cam.transform.position=actor.transform.position+new Vector3(1.3f,1.5f,2.3f);cam.transform.LookAt(actor.transform.position+Vector3.up*1.1f);yield return null;}marks.Add("sleep,"+frame);walk.gait=0;walk.seated=true;var book=CinematicBook.Create(actor.transform);for(float t=0;t<1.7f;t+=Time.deltaTime){actor.transform.position=new Vector3(-40,-.37f*Mathf.SmoothStep(0,1,t/.7f),9.1f);walk.sleep=Mathf.Clamp01((t-.6f)/1.1f);cam.transform.position=new Vector3(-41.2f,1.1f,10.7f);cam.transform.LookAt(actor.transform.position+Vector3.up*1.05f);yield return null;}for(int i=0;i<5;i++){float x=i*40;foreach(var l in FindObjectsByType<Light>())if(l.type!=LightType.Directional)l.enabled=Mathf.Abs(l.transform.position.x-x)<15;for(int angle=0;angle<2;angle++){marks.Add("map"+(i+1)+"_"+angle+","+frame);cam.fieldOfView=82;for(int k=0;k<36;k++){float t=k/35f;cam.transform.position=angle==0?new Vector3(x-3.5f+t*.8f,i==0?3.7f:2.9f,1.7f+t*1.8f):new Vector3(x+3.4f-t*.6f,i==0?3.6f:2.8f,(i==3?14:22)-t*1.2f);cam.transform.LookAt(new Vector3(x,1,i==3?7:12));yield return null;}}}
 File.WriteAllLines(Path.Combine(folder,"poses.csv"),poses);File.WriteAllLines(Path.Combine(folder,"shots.csv"),marks);File.WriteAllText(Path.Combine(folder,"complete.txt"),frame.ToString());cam.targetTexture=null;Time.captureFramerate=0;
 #if UNITY_EDITOR
 UnityEditor.EditorApplication.isPlaying=false;
 #endif
 }
 void LateUpdate(){if(!rt)return;var actor=GameObject.Find("Carlinhos opening");if(frame>=165&&frame<180){foreach(var t in actor.GetComponentsInChildren<Transform>())if(t.name.EndsWith("LeftFoot")||t.name.EndsWith("RightFoot")||t.name=="Hips")poses.Add(frame+","+t.name+","+t.position.y.ToString("F4",System.Globalization.CultureInfo.InvariantCulture));}cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(folder,frame.ToString("D5")+".jpg"),tex.EncodeToJPG(94));RenderTexture.active=null;frame++;}
}
